import java.util.StringTokenizer

fun main() {
    val input = generateSequence(::readLine)
        .flatMap { StringTokenizer(it).asSequence().map { token -> token.toString() } }
        .toList()

    val ta = input[1].toInt()
    val b = input[2].toInt()
    val tb = input[3].toInt()

    val (hour, minute) = input[4].split(":").map(String::toInt)
    val departure = hour * 60 + minute
    val arrival = departure + ta

    var count = 0
    var oppositeDeparture = 5 * 60

    while (oppositeDeparture < 24 * 60) {
        if (oppositeDeparture < arrival && oppositeDeparture + tb > departure) {
            count++
        }
        oppositeDeparture += b
    }

    print(count)
}
